package apextest

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// Exact owned API67 source admitted by the eighteen-method Salesforce packet.
func TestRunC5BulkTypedProof(t *testing.T) {
	home := os.Getenv("GLADE_DATAWEAVE_APEX_TEST_HOME")
	if home == "" {
		t.Skip("requires explicitly installed DataWeave toolchain")
	}
	t.Setenv("GLADE_HOME", home)
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC5BulkTypedProof.cls"), "@IsTest\nprivate class GladeC5BulkTypedProof {\n    @IsTest static void transformsTwoDateInputs() {\n        Date first = Date.newInstance(2024,2,28);\n        Date second = Date.newInstance(2024,12,31);\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInDate');\n        System.assertEquals('\"2024-02-29\"', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('\"2025-01-01\"', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoDatetimeInputs() {\n        Datetime first = Datetime.newInstanceGmt(2024,2,28,23,59,59);\n        Datetime second = Datetime.newInstanceGmt(2024,12,31,23,59,59);\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInDatetime');\n        System.assertEquals('\"2024-02-29 00:00:00\"', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('\"2025-01-01 00:00:00\"', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoTimeInputs() {\n        Time first = Time.newInstance(1,2,3,4);\n        Time second = Time.newInstance(23,59,59,999);\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInTime');\n        System.assertEquals('\"01:02:04.004\"', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('\"00:00:00.999\"', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoLongInputs() {\n        Long first = Long.valueOf('2147483648');\n        Long second = Long.valueOf('9007199254740991');\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInLong');\n        System.assertEquals('2147483650', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('9007199254740993', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoIdInputs() {\n        Id first = (Id)'001000000000001';\n        Id second = (Id)'001000000000002';\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInId');\n        System.assertEquals('\"001000000000001-owned\"', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('\"001000000000002-owned\"', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoBlobInputs() {\n        Blob first = Blob.valueOf('first-owned');\n        Blob second = Blob.valueOf('second-owned');\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInBlob');\n        System.assertEquals('\"Zmlyc3Qtb3duZWQ=\"', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('\"c2Vjb25kLW93bmVk\"', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void transformsTwoCustomInputs() {\n        GladeC5BulkValue first = new GladeC5BulkValue();\n        first.label = 'first'; first.amount = 1.25; first.tags = new List<String>{'a','b'};\n        GladeC5BulkValue second = new GladeC5BulkValue();\n        second.label = 'second'; second.amount = 2.5; second.tags = new List<String>{'c'};\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInCustom');\n        Map<String,Object> one = (Map<String,Object>)JSON.deserializeUntyped(script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        Map<String,Object> two = (Map<String,Object>)JSON.deserializeUntyped(script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n        System.assertEquals('FIRST', one.get('label')); System.assertEquals(Decimal.valueOf('2.5'), one.get('amount')); System.assertEquals(2, one.get('count'));\n        System.assertEquals('SECOND', two.get('label')); System.assertEquals(Decimal.valueOf('5'), two.get('amount')); System.assertEquals(1, two.get('count'));\n    }\n    @IsTest static void transformsTwoSetInputs() {\n        Set<String> first = new Set<String>{'a','b'};\n        Set<String> second = new Set<String>{'c','d','e'};\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkInSet');\n        System.assertEquals('2', script.execute(new Map<String,Object>{'payload'=>first}).getValueAsString());\n        System.assertEquals('3', script.execute(new Map<String,Object>{'payload'=>second}).getValueAsString());\n    }\n    @IsTest static void returnsExactDateValue() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutDate');\n        Object value = script.execute(new Map<String,Object>()).getValue();\n        System.assert(value instanceof Date, 'Expected Date output');\n        System.assertEquals(Date.newInstance(2024,2,29), (Date)value);\n    }\n    @IsTest static void returnsExactDatetimeValue() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutDatetime');\n        Object value = script.execute(new Map<String,Object>()).getValue();\n        System.assert(value instanceof Datetime, 'Expected Datetime output');\n        System.assertEquals(Datetime.newInstanceGmt(2024,2,29,1,2,3).getTime(), ((Datetime)value).getTime());\n    }\n    @IsTest static void returnsExactTimeValue() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutTime');\n        Object value = script.execute(new Map<String,Object>()).getValue();\n        System.assert(value instanceof Time, 'Expected Time output');\n        System.assertEquals(Time.newInstance(1,2,3,4), (Time)value);\n    }\n    @IsTest static void returnsExactBlobValue() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutBlob');\n        Object value = script.execute(new Map<String,Object>()).getValue();\n        System.assert(value instanceof Blob, 'Expected Blob output');\n        System.assertEquals('6f776e65642d6279746573', EncodingUtil.convertToHex((Blob)value));\n    }\n    @IsTest static void returnsCustomClassIdentity() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutCustom');\n        Object raw = script.execute(new Map<String,Object>()).getValue();\n        System.assert(raw instanceof GladeC5BulkValue, 'Expected owned Apex class');\n        GladeC5BulkValue value = (GladeC5BulkValue)raw;\n        System.assertEquals('owned', value.label); System.assertEquals(Decimal.valueOf('1.25'), value.amount);\n        System.assertEquals(new List<String>{'a','b'}, value.tags);\n    }\n    @IsTest static void returnsListElementsAndIdentity() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutList');\n        Object raw = script.execute(new Map<String,Object>()).getValue();\n        System.assert(raw instanceof List<Object>, 'Expected Apex List');\n        List<Object> values = (List<Object>)raw;\n        System.assertEquals(2, values.size());\n        System.assert(values[0] instanceof Decimal, 'Expected first Decimal'); System.assert(values[1] instanceof Decimal, 'Expected second Decimal');\n        System.assertEquals(Decimal.valueOf('2'), values[0]); System.assertEquals(Decimal.valueOf('3'), values[1]);\n    }\n    @IsTest static void returnsMapElementsAndIdentity() {\n        String phase = 'create';\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkOutMap');\n        phase = 'execute';\n        DataWeave.Result result = null;\n        Boolean caught = false;\n        try {\n            result = script.execute(new Map<String,Object>());\n            phase = 'complete';\n        } catch (DataWeaveScriptException error) {\n            caught = true;\n            System.assertEquals('execute', phase);\n            System.assertEquals('System.DataWeaveScriptException', error.getTypeName());\n            System.assertEquals('Need to specify Apex object type with \\'as\\' clause, while writing application/apex at \\n4| {label:\"owned\",count:7,enabled:true,missing:null}\\n   ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^.\\n\\n4| {label:\"owned\",count:7,enabled:true,missing:null}\\n   ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\\nTrace:\\n  at anonymous::main (line: 4, column: 1)', error.getMessage());\n        }\n        System.assertEquals(true, caught, 'Untyped object output must fail during execute');\n        System.assertEquals(null, result, 'A failed execute must not return a result');\n    }\n    @IsTest static void rendersApexStringAsString() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkAsStringString');\n        String value = script.execute(new Map<String,Object>()).getValueAsString();\n        System.assertEquals('owned-text', value);\n    }\n    @IsTest static void rendersApexNumberAsString() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkAsStringNumber');\n        String value = script.execute(new Map<String,Object>()).getValueAsString();\n        System.assertEquals('12.5', value);\n    }\n    @IsTest static void rendersApexListAsString() {\n        DataWeave.Script script = DataWeave.Script.createScript('gladeC5BulkAsStringList');\n        String value = script.execute(new Map<String,Object>()).getValueAsString();\n        System.assertEquals('(2, 3)', value);\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC5BulkTypedProof.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC5BulkValue.cls"), "public class GladeC5BulkValue {\n    public String label;\n    public Decimal amount;\n    public List<String> tags;\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC5BulkValue.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringList.dwl"), "%dw 2.0\noutput application/apex\n---\n[2,3]\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringList.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringNumber.dwl"), "%dw 2.0\noutput application/apex\n---\n12.5\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringNumber.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringString.dwl"), "%dw 2.0\noutput application/apex\n---\n\"owned-text\"\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkAsStringString.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInBlob.dwl"), "%dw 2.0\nimport toBase64 from dw::core::Binaries\ninput payload application/java\noutput application/json indent=false\n---\ntoBase64(payload)\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInBlob.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInCustom.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\n{label:upper(payload.label),amount:payload.amount * 2,count:sizeOf(payload.tags)}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInCustom.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInDate.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\n(payload + |P1D|) as String {format:\"yyyy-MM-dd\"}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInDate.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInDatetime.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\n(payload + |PT1S|) as String {format:\"yyyy-MM-dd HH:mm:ss\"}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInDatetime.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInId.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\n(payload as String)[0 to 14] ++ \"-owned\"\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInId.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInLong.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\npayload + 2\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInLong.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInSet.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\nsizeOf(payload)\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInSet.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInTime.dwl"), "%dw 2.0\ninput payload application/java\noutput application/json indent=false\n---\n(payload + |PT1S|) as String {format:\"HH:mm:ss.SSS\"}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkInTime.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutBlob.dwl"), "%dw 2.0\noutput application/apex\n---\n\"owned-bytes\" as Binary {encoding:\"UTF-8\"}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutBlob.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutCustom.dwl"), "%dw 2.0\noutput application/apex\n---\n{label:\"owned\",amount:1.25,tags:[\"a\",\"b\"]} as Object {class:\"GladeC5BulkValue\"}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutCustom.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutDate.dwl"), "%dw 2.0\noutput application/apex\n---\n|2024-02-29|\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutDate.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutDatetime.dwl"), "%dw 2.0\noutput application/apex\n---\n|2024-02-29T01:02:03.004Z|\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutDatetime.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutList.dwl"), "%dw 2.0\noutput application/apex\n---\n[2,3]\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutList.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutMap.dwl"), "%dw 2.0\noutput application/apex\n---\n{label:\"owned\",count:7,enabled:true,missing:null}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutMap.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutTime.dwl"), "%dw 2.0\noutput application/apex\n---\n|01:02:03.004|\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/dw/gladeC5BulkOutTime.dwl-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DataWeaveResource xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><isGlobal>false</isGlobal></DataWeaveResource>\n")
	writeFile(t, filepath.Join(root, "manifest/package.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Package xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n  <types>\n    <members>GladeC5BulkTypedProof</members>\n    <members>GladeC5BulkValue</members>\n    <name>ApexClass</name>\n  </types>\n  <types>\n    <members>gladeC5BulkInDate</members>\n    <members>gladeC5BulkInDatetime</members>\n    <members>gladeC5BulkInTime</members>\n    <members>gladeC5BulkInLong</members>\n    <members>gladeC5BulkInId</members>\n    <members>gladeC5BulkInBlob</members>\n    <members>gladeC5BulkInCustom</members>\n    <members>gladeC5BulkInSet</members>\n    <members>gladeC5BulkOutDate</members>\n    <members>gladeC5BulkOutDatetime</members>\n    <members>gladeC5BulkOutTime</members>\n    <members>gladeC5BulkOutBlob</members>\n    <members>gladeC5BulkOutCustom</members>\n    <members>gladeC5BulkOutList</members>\n    <members>gladeC5BulkOutMap</members>\n    <members>gladeC5BulkAsStringString</members>\n    <members>gladeC5BulkAsStringNumber</members>\n    <members>gladeC5BulkAsStringList</members>\n    <name>DataWeaveResource</name>\n  </types>\n  <version>67.0</version>\n</Package>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\n  \"sourceApiVersion\": \"67.0\",\n  \"packageDirectories\": [\n    {\n      \"path\": \"force-app\",\n      \"default\": true\n    }\n  ]\n}\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 18 || got.Passed != 18 {
		data, _ := json.Marshal(run)
		t.Fatalf("admitted C5 typed contract failed: %s", data)
	}
}
